package me.minis.ledger;
import android.content.*;import android.database.*;import android.database.sqlite.*;import org.json.*;import java.util.*;import android.app.*;
/** Local plans only: reminders never manufacture a payment entry. */
public final class LedgerPlans {
 static void install(SQLiteDatabase db){db.execSQL("CREATE TABLE IF NOT EXISTS budgets(category TEXT PRIMARY KEY,cents INTEGER NOT NULL)");db.execSQL("CREATE TABLE IF NOT EXISTS reminders(id TEXT PRIMARY KEY,title TEXT NOT NULL,cents INTEGER NOT NULL,due INTEGER NOT NULL,cycle TEXT NOT NULL,day INTEGER NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,notified INTEGER NOT NULL DEFAULT 0)");}
 static void exclude(LedgerDb h,long id,boolean excluded){ContentValues v=new ContentValues();v.put("excluded",excluded?1:0);if(h.getWritableDatabase().update("entries",v,"_id=? AND status IN ('confirmed','review')",new String[]{""+id})!=1)throw new IllegalStateException("记录不存在或已变化，请刷新");}
 static long[] month(long now){Calendar c=Calendar.getInstance();c.setTimeInMillis(now);c.set(Calendar.DAY_OF_MONTH,1);c.set(Calendar.HOUR_OF_DAY,0);c.set(Calendar.MINUTE,0);c.set(Calendar.SECOND,0);c.set(Calendar.MILLISECOND,0);long start=c.getTimeInMillis();c.add(Calendar.MONTH,1);return new long[]{start,c.getTimeInMillis()};}
 static JSONObject state(Context c,LedgerDb h)throws Exception{SQLiteDatabase db=h.getReadableDatabase();long now=System.currentTimeMillis();long[] range=month(now);JSONArray budgets=new JSONArray(),reminders=new JSONArray();try(Cursor r=db.rawQuery("SELECT category,cents FROM budgets ORDER BY category",null)){while(r.moveToNext()){String cat=r.getString(0);String filter=cat.isEmpty()?"":" AND category=?";String[] args=cat.isEmpty()?new String[]{""+range[0],""+Math.min(range[1],now+1)}:new String[]{""+range[0],""+Math.min(range[1],now+1),cat};long used=FinanceQueries.budget(db,range[0],Math.min(range[1],now+1),cat);budgets.put(new JSONObject().put("category",cat).put("cents",r.getLong(1)).put("used",Math.max(0,used)));}}
  try(Cursor r=db.rawQuery("SELECT id,title,cents,due,cycle,day,enabled,notified FROM reminders ORDER BY due,id",null)){while(r.moveToNext()){JSONObject o=new JSONObject();for(int i=0;i<8;i++)o.put(r.getColumnName(i),i<2||i==4?r.getString(i):r.getLong(i));reminders.put(o);}}
  return new JSONObject().put("budgets",budgets).put("budgetStyle",BudgetUsage.style(c)).put("reminders",reminders).put("backup",BackupVault.state(c));
 }
 static void budget(LedgerDb h,JSONObject p)throws Exception{String cat=p.optString("category","");long cents=p.getLong("cents");if(!cat.isEmpty()&&!Arrays.asList(LedgerDb.CATEGORIES).contains(cat)||cents<0||cents>99999999999L)throw new IllegalArgumentException("预算金额或分类不合法");if(cents==0)h.getWritableDatabase().delete("budgets","category=?",new String[]{cat});else{ContentValues v=new ContentValues();v.put("category",cat);v.put("cents",cents);h.getWritableDatabase().insertWithOnConflict("budgets",null,v,SQLiteDatabase.CONFLICT_REPLACE);}h.notifyChanged();}
 static void reminder(LedgerDb h,JSONObject p)throws Exception{SQLiteDatabase db=h.getWritableDatabase();String id=p.optString("id","");if(!id.isEmpty()&&!id.matches("[a-f0-9-]{36}"))throw new IllegalArgumentException("提醒编号不合法");if(p.optBoolean("delete")){db.delete("reminders","id=?",new String[]{id});return;}String title=p.getString("title").trim(),cycle=p.getString("cycle");long cents=p.getLong("cents"),due=p.getLong("due");if(title.isEmpty()||title.length()>60||cents<0||cents>99999999999L||due<0||due>4102444800000L||!Arrays.asList("once","month","year").contains(cycle))throw new IllegalArgumentException("请核对提醒名称、金额和日期");if(id.isEmpty()){if(DatabaseUtils.longForQuery(db,"SELECT count(*) FROM reminders",null)>=50)throw new IllegalArgumentException("最多保留50项提醒");id=UUID.randomUUID().toString();}Calendar d=Calendar.getInstance();d.setTimeInMillis(due);ContentValues v=new ContentValues();v.put("id",id);v.put("title",title);v.put("cents",cents);v.put("due",due);int anchorDay=d.get(Calendar.DAY_OF_MONTH);try(Cursor prior=db.rawQuery("SELECT due,cycle,day FROM reminders WHERE id=?",new String[]{id})){if(prior.moveToFirst()&&prior.getLong(0)==due&&prior.getString(1).equals(cycle))anchorDay=prior.getInt(2);}v.put("day",anchorDay);v.put("cycle",cycle);v.put("enabled",p.optBoolean("enabled",true)?1:0);v.put("notified",0);db.insertWithOnConflict("reminders",null,v,SQLiteDatabase.CONFLICT_REPLACE);}
 static long advance(long due,String cycle,int day,long now){Calendar d=Calendar.getInstance();d.setTimeInMillis(due);if(cycle.equals("once"))return due;for(int i=0;i<2500&&d.getTimeInMillis()<=now;i++){d.set(Calendar.DAY_OF_MONTH,1);d.add(cycle.equals("month")?Calendar.MONTH:Calendar.YEAR,1);d.set(Calendar.DAY_OF_MONTH,Math.min(day,d.getActualMaximum(Calendar.DAY_OF_MONTH)));}return d.getTimeInMillis();}
 static void acknowledge(LedgerDb h,String id){SQLiteDatabase db=h.getWritableDatabase();try(Cursor c=db.rawQuery("SELECT due,cycle,day FROM reminders WHERE id=?",new String[]{id})){if(!c.moveToFirst())throw new IllegalStateException("提醒不存在");long due=c.getLong(0),now=System.currentTimeMillis();if(due>now)throw new IllegalStateException("尚未到期；如需提前调整请编辑日期");ContentValues v=new ContentValues();if(c.getString(1).equals("once"))v.put("enabled",0);else v.put("due",advance(due,c.getString(1),c.getInt(2),now));v.put("notified",0);db.update("reminders",v,"id=?",new String[]{id});}}
 static String backup(SQLiteDatabase db)throws Exception{JSONObject o=new JSONObject();for(String t:new String[]{"budgets","reminders"}){JSONArray a=new JSONArray();try(Cursor c=db.rawQuery("SELECT * FROM "+t,null)){while(c.moveToNext())a.put(UndoLog.row(c));}o.put(t,a);}String value=o.toString();if(value.length()>22000||JSONObject.quote(value).length()>24000)throw new IllegalStateException("计划备份过大");return value;}
 static void restore(SQLiteDatabase db,String text)throws Exception{if(text==null||text.isEmpty())return;JSONObject p=new JSONObject(text);JSONArray budgets=p.optJSONArray("budgets"),reminders=p.optJSONArray("reminders");if(budgets==null||reminders==null||budgets.length()>8||reminders.length()>50)throw new IllegalArgumentException("预算或提醒备份不合法");for(int i=0;i<budgets.length();i++){JSONObject o=budgets.getJSONObject(i);String cat=o.getString("category");long cents=o.getLong("cents");if(!cat.isEmpty()&&!Arrays.asList(LedgerDb.CATEGORIES).contains(cat)||cents<=0||cents>99999999999L)throw new IllegalArgumentException("预算备份不合法");ContentValues v=new ContentValues();v.put("category",cat);v.put("cents",cents);db.insertWithOnConflict("budgets",null,v,SQLiteDatabase.CONFLICT_IGNORE);}for(int i=0;i<reminders.length();i++){JSONObject o=reminders.getJSONObject(i);String id=o.getString("id"),title=o.getString("title"),cycle=o.getString("cycle");long due=o.getLong("due"),cents=o.getLong("cents");int day=o.getInt("day");if(!id.matches("[a-f0-9-]{36}")||title.trim().isEmpty()||title.length()>60||cents<0||cents>99999999999L||due<0||due>4102444800000L||day<1||day>31||!Arrays.asList("once","month","year").contains(cycle))throw new IllegalArgumentException("提醒备份不合法");if(DatabaseUtils.longForQuery(db,"SELECT count(*) FROM reminders WHERE id=?",new String[]{id})==0&&DatabaseUtils.longForQuery(db,"SELECT count(*) FROM reminders",null)>=50)throw new IllegalArgumentException("恢复后提醒超过50项");ContentValues v=new ContentValues();v.put("id",id);v.put("title",title);v.put("cycle",cycle);v.put("due",due);v.put("cents",cents);v.put("day",day);v.put("enabled",0);v.put("notified",0);db.insertWithOnConflict("reminders",null,v,SQLiteDatabase.CONFLICT_IGNORE);}}
 static void check(Context context,LedgerDb h){SQLiteDatabase db=h.getWritableDatabase();long now=System.currentTimeMillis();try{NotificationManager nm=(NotificationManager)context.getSystemService(Context.NOTIFICATION_SERVICE);nm.createNotificationChannel(new NotificationChannel("plans336","账单与预算提醒",NotificationManager.IMPORTANCE_DEFAULT));if(!nm.areNotificationsEnabled())return;int count=(int)DatabaseUtils.longForQuery(db,"SELECT count(*) FROM reminders WHERE enabled=1 AND due<=? AND notified<>due",new String[]{""+now});if(count>0){Notification n=new Notification.Builder(context,"plans336").setSmallIcon(SummaryNotice.getNoticeIcon(context)).setContentTitle("有 "+count+" 项账单／订阅到期").setContentText("打开轻记核对，未自动记账或扣款").setVisibility(Notification.VISIBILITY_PRIVATE).setAutoCancel(true).setContentIntent(PendingIntent.getActivity(context,336,new Intent(context,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE)).build();nm.notify(33601,n);db.execSQL("UPDATE reminders SET notified=due WHERE enabled=1 AND due<=? AND notified<>due",new Object[]{now});}long[] range=month(now);String month=""+range[0];boolean alert=false;try(Cursor r=db.rawQuery("SELECT category,cents FROM budgets",null)){while(r.moveToNext()){String cat=r.getString(0),filter=cat.isEmpty()?"":" AND category=?";long used=FinanceQueries.budget(db,range[0],Math.min(range[1],now+1),cat);String key="budget_warn_"+cat,stamp=month+":"+r.getLong(1);if(used>=r.getLong(1)&&!LedgerDb.prefs(context).getString(key,"").equals(stamp)){alert=true;LedgerDb.prefs(context).edit().putString(key,stamp).apply();}}}if(alert)nm.notify(33602,new Notification.Builder(context,"plans336").setSmallIcon(SummaryNotice.getNoticeIcon(context)).setContentTitle("本月有预算已用完").setContentText("打开轻记查看总预算与分类预算").setVisibility(Notification.VISIBILITY_PRIVATE).setAutoCancel(true).setContentIntent(PendingIntent.getActivity(context,336,new Intent(context,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE)).build());}catch(Exception e){PowerDetail.count("plan_reminder_error");}}
}
